from .errors import AliasCollision
class Registry:
 def __init__(self,rows):
  self.by_id={}
  self.by_alias={}
  alias_owner={}
  for row in rows:
   item_id,alias=row[0],row[1]
   if alias in alias_owner:
    other=alias_owner[alias]
    raise AliasCollision(f"{min(other,item_id)} and {max(other,item_id)} share alias {alias!r}")
   alias_owner[alias]=item_id
   self.by_id[item_id]=row
   self.by_alias[alias]=row
 def by_exact_id(self,item_id): return self.by_id[item_id]
 def by_name(self,alias): return self.by_alias[alias]

